result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/toasts/src/ToastProvider.test.jsx", "content": "import React, { act } from "react";
import { describe, it, expect, beforeEach, afterEach, vi } from "vitest";
import { render, screen, fireEvent, cleanup } from "@testing-library/react";
import { ToastProvider, useToast } from "./ToastProvider";

function Harness({ onReady }) {
  const { push } = useToast();
  onReady(push);
  return null;
}

function setup() {
  const pushes = [];
  const view = render(
    <ToastProvider>
      <Harness onReady={(push) => pushes.push(push)} />
    </ToastProvider>
  );
  // onReady runs once per render; keep only the first (stable) push fn.
  const push = (message, opts) => act(() => Promise.resolve(pushes[0](message, opts)));
  return { push, ...view };
}

const getToasts = () => screen.queryAllByTestId("toast");
const textOf = (el) => el.textContent;

beforeEach(() => {
  vi.useFakeTimers();
});

afterEach(() => {
  cleanup();
  vi.useRealTimers();
});

describe("ToastProvider", () => {
  it("renders pushed toasts in a polite live region", () => {
    setup().push("Hello");
    const region = screen.getByRole("region", { name: "Notifications" });
    expect(region).toBeTruthy();
    const live = region.querySelector("[aria-live='polite']");
    expect(live).toBeTruthy();
    expect(getToasts()).toHaveLength(1);
    expect(textOf(getToasts()[0])).toContain("Hello");
  });

  it("auto-dismisses a toast after its duration", () => {
    const { push } = setup();
    push("fleeting", { durationMs: 3000 });
    expect(getToasts()).toHaveLength(1);
    act(() => vi.advanceTimersByTime(2999));
    expect(getToasts()).toHaveLength(1);
    act(() => vi.advanceTimersByTime(1));
    expect(getToasts()).toHaveLength(0);
  });

  it("uses the default duration when none is given", () => {
    const { push } = setup();
    push("default-timing");
    act(() => vi.advanceTimersByTime(4999));
    expect(getToasts()).toHaveLength(1);
    act(() => vi.advanceTimersByTime(1));
    expect(getToasts()).toHaveLength(0);
  });

  it("stacks newest last and queues the fourth until one expires", () => {
    const { push } = setup();
    push("one", { durationMs: 1000 });
    push("two", { durationMs: 5000 });
    push("three", { durationMs: 6000 });
    push("four", { durationMs: 7000 });

    // Only three visible; "one" is first, no sign of "four" yet.
    let toasts = getToasts();
    expect(toasts).toHaveLength(3);
    expect(textOf(toasts[0])).toContain("one");
    expect(textOf(toasts[2])).toContain("three");
    expect(screen.queryByText(/four/)).toBeNull();

    // After "one" expires, "four" slides in at the bottom.
    act(() => vi.advanceTimersByTime(1000));
    toasts = getToasts();
    expect(toasts).toHaveLength(3);
    expect(textOf(toasts[0])).toContain("two");
    expect(textOf(toasts[2])).toContain("four");

    // The queued toast gets its full duration once visible.
    act(() => vi.advanceTimersByTime(6999));
    expect(getToasts()).toHaveLength(3);
    act(() => vi.advanceTimersByTime(1));
    expect(getToasts()).toHaveLength(0);
  });

  it("pauses the countdown while hovered and resumes after mouse out", () => {
    const { push } = setup();
    push("hover-me", { durationMs: 2000 });
    const toast = getToasts()[0];

    // Hover: pause the countdown.
    fireEvent.mouseOver(toast);

    // Advance well past the original duration — still present.
    act(() => vi.advanceTimersByTime(10000));
    expect(getToasts()).toHaveLength(1);
    expect(textOf(getToasts()[0])).toContain("hover-me");

    // Mouse out: remaining time resumes and dismisses shortly after.
    fireEvent.mouseOut(getToasts()[0]);
    act(() => vi.advanceTimersByTime(1999));
    expect(getToasts()).toHaveLength(1);
    act(() => vi.advanceTimersByTime(1));
    expect(getToasts()).toHaveLength(0);
  });

  it("only counts un-hovered time toward dismissal", () => {
    const { push } = setup();
    push("half-hovered", { durationMs: 4000 });

    act(() => vi.advanceTimersByTime(1500));
    fireEvent.mouseOver(getToasts()[0]);
    act(() => vi.advanceTimersByTime(50000));
    expect(getToasts()).toHaveLength(1);

    // Exactly 2500ms of countdown remain after mouse out.
    fireEvent.mouseOut(getToasts()[0]);
    act(() => vi.advanceTimersByTime(2499));
    expect(getToasts()).toHaveLength(1);
    act(() => vi.advanceTimersByTime(1));
    expect(getToasts()).toHaveLength(0);
  });

  it("supports manual dismissal via a labelled dismiss button", () => {
    const { push } = setup();
    push("manual", { durationMs: 60000 });
    push("other", { durationMs: 60000 });

    const button = screen.getByRole("button", {
      name: "Dismiss manual",
    });
    expect(button).toBeTruthy();
    fireEvent.click(button);

    const toasts = getToasts();
    expect(toasts).toHaveLength(1);
    expect(textOf(toasts[0])).toContain("other");
    // No lingering timers: everything survives past any duration.
    act(() => vi.advanceTimersByTime(120000));
    expect(getToasts()).toHaveLength(1);
  });

  it("throws when useToast is used outside the provider", () => {
    const spy = vi.spyOn(console, "error").mockImplementation(() => {});
    function Orphan() {
      useToast();
      return null;
    }
    expect(() => render(<Orphan />)).toThrow(
      /useToast\(\) must be used within a <ToastProvider>/
    );
    spy.mockRestore();
  });
});
"})
